import type { ColDef } from 'ag-grid-community'
import type { Position } from '../api/types'
import { formatPrice, formatQuantity } from '../lib/format'

export const positionColumns: ColDef<Position>[] = [
  { field: 'symbol', headerName: 'Symbol', cellDataType: 'text', minWidth: 80 },
  {
    field: 'netQuantity',
    headerName: 'Net Qty',
    type: 'rightAligned',
    valueFormatter: (p) => formatQuantity(p.value ?? 0),
    cellClassRules: { 'short-position': (p) => (p.value ?? 0) < 0 },
  },
  {
    field: 'averageCost',
    headerName: 'Avg Cost',
    type: 'rightAligned',
    valueFormatter: (p) => formatPrice(p.value ?? 0),
  },
]

export const positionDefaultColDef: ColDef<Position> = { sortable: true, flex: 1, minWidth: 80 }
// `locale` and `timeZone` default to the browser's; tests pass them explicitly.

export function formatTimestamp(iso: string, locale?: string, timeZone?: string): string {
  return new Intl.DateTimeFormat(locale, {
    year: 'numeric',
    month: 'short',
    day: '2-digit',
    hour: '2-digit',
    minute: '2-digit',
    second: '2-digit',
    hourCycle: 'h23',
    timeZone,
  }).format(new Date(iso))
}

export function formatQuantity(value: number, locale?: string): string {
  return value.toLocaleString(locale, { maximumFractionDigits: 4 })
}

export function formatPrice(value: number, locale?: string): string {
  return value.toLocaleString(locale, { minimumFractionDigits: 2, maximumFractionDigits: 4 })
}

export function formatMoney(value: number, locale?: string): string {
  return value.toLocaleString(locale, { minimumFractionDigits: 2, maximumFractionDigits: 2 })
}
import { definePreset } from '@primeuix/themes'
import Aura from '@primeuix/themes/aura'
import { themeQuartz } from 'ag-grid-community'

const palette = (name: string) =>
  Object.fromEntries(
    [50, 100, 200, 300, 400, 500, 600, 700, 800, 900, 950].map((shade) => [
      shade,
      `{${name}.${shade}}`,
    ]),
  )

export const primePreset = definePreset(Aura, {
  semantic: { primary: palette('sky') },
})

// The grid reads PrimeVue's CSS variables so both libraries share one palette.
export const gridTheme = themeQuartz.withParams({
  accentColor: 'var(--p-primary-500)',
  backgroundColor: 'var(--p-surface-0)',
  foregroundColor: 'var(--p-surface-700)',
